//! Golden tests: the Rust transform must produce exactly what the live Python
//! parser (`scripts/vps/scrapers/market_sync.py`) produces for the same DSE
//! payload. Expected files are generated by `tests/tools/gen_expected.py`.

use price_feed::transform::{parse_feed, MIN_STOCKS};
use serde_json::Value;

fn load(path: &str) -> Value {
    let full = format!("{}/tests/fixtures/{path}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(&full).expect(&full)).expect("valid JSON")
}

/// Bit-exact comparison: numbers must match to the last bit (so 0.0 vs -0.0
/// and 0.1+0.2 style drift are caught), and key sets must be identical.
fn assert_same(actual: &Value, expected: &Value, path: &str) {
    match (actual, expected) {
        (Value::Number(a), Value::Number(e)) => {
            let (a, e) = (a.as_f64().unwrap(), e.as_f64().unwrap());
            assert_eq!(a.to_bits(), e.to_bits(), "{path}: {a} != {e}");
        }
        (Value::Object(a), Value::Object(e)) => {
            let ak: Vec<_> = a.keys().collect();
            let ek: Vec<_> = e.keys().collect();
            assert_eq!(ak, ek, "{path}: keys differ");
            for (k, ev) in e {
                assert_same(&a[k], ev, &format!("{path}.{k}"));
            }
        }
        (Value::Array(a), Value::Array(e)) => {
            assert_eq!(a.len(), e.len(), "{path}: length differs");
            for (i, (av, ev)) in a.iter().zip(e).enumerate() {
                assert_same(av, ev, &format!("{path}[{i}]"));
            }
        }
        _ => assert_eq!(actual, expected, "{path}"),
    }
}

fn check(fixture: &str, expected: &str) -> usize {
    let feed = parse_feed(&load(fixture));
    let expected = load(expected);
    let stocks = Value::Array(feed.stocks.into_iter().map(Value::Object).collect());
    assert_same(&stocks, &expected["stocks"], fixture);
    assert_eq!(
        feed.market_status.map(Value::from).unwrap_or(Value::Null),
        expected["marketStatus"],
        "{fixture}: marketStatus"
    );
    stocks.as_array().unwrap().len()
}

#[test]
fn live_feed_closed_session_matches_python() {
    let n = check("closed_2026-11-18.json", "closed_2026-11-18.expected.json");
    assert!(n >= MIN_STOCKS, "real feed should clear the minimum count, got {n}");
}

#[test]
fn edge_cases_match_python() {
    check("edge_cases.json", "edge_cases.expected.json");
}

#[test]
fn real_session_2026_11_19_matches_python() {
    // Pre-open (bonds missing, status Closed), mid-session (Open, 22 bonds absent
    // all session) and the 14:00 close (all 419 back).
    for (name, rows) in [("preopen_2026-11-19", 395), ("open_2026-11-19", 397), ("close_2026-11-19", 419)] {
        let n = check(&format!("{name}.json"), &format!("{name}.expected.json"));
        assert_eq!(n, rows, "{name}");
    }
}
